contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}
    function run(uint val, uint val2) public payable {
        uint before = c.MinSum(); if (__ESBMC_reverted()) return;
        c.SetMinSum(val); if (__ESBMC_reverted()) return;
        uint afterFirst = c.MinSum(); if (__ESBMC_reverted()) return;
        c.SetMinSum(val2); if (__ESBMC_reverted()) return;
        uint afterSecond = c.MinSum(); if (__ESBMC_reverted()) return;
        assert(afterFirst == val && afterSecond == val2 && before == 0);
    }
}

